parameters.jsCode:
// Format and structure discovered results for clean n8n inspection
const data = $input.first().json;

return [{
  json: {
    status: 'SUCCESS',
    runId: data.runId,
    timestamp: data.timestamp,
    summary: {
      queriesExecuted: data.summary?.queries || 6,
      rawDiscovered: data.summary?.rawDiscovered || 0,
      uniqueOpportunities: data.summary?.uniqueOpportunities || 0,
      qualifiedCount: data.summary?.qualified || 0,
      rejectedCount: data.summary?.rejected || 0,
    },
    qualifiedOpportunities: (data.qualified || []).map((q) => ({
      title: q.opportunity?.title,
      company: q.opportunity?.company,
      matchScore: q.matchScore,
      reason: q.reason,
      source: q.opportunity?.primarySource || q.opportunity?.source,
      sourceUrl: q.opportunity?.sourceUrl,
      applicationUrl: q.opportunity?.applicationUrl,
      remote: q.opportunity?.remote,
      matchedSkills: q.matchedSkills,
    })),
    rejectionSample: (data.rejected || []).slice(0, 5).map((r) => ({
      title: r.opportunity?.title,
      company: r.opportunity?.company,
      reason: r.reason,
    })),
  }
}];

// Format discovery failure details cleanly for n8n execution viewer
const data = $input.first().json;

return [{
  json: {
    status: 'FAILED',
    errorCode: data.error?.code || 'DISCOVERY_ERROR',
    errorMessage: data.error?.message || 'Unknown discovery error occurred',
    timestamp: new Date().toISOString(),
  }
}];
